package com.narudzbine.identity.infrastructure.web;
import com.narudzbine.inventory.api.*;
import com.narudzbine.inventory.api.VendorInventory.*;
import com.narudzbine.identity.api.*;
import com.narudzbine.identity.application.*;
import com.narudzbine.organizations.api.*;
import com.narudzbine.shared.api.ResourceRevisions;
import jakarta.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.time.*;
import java.util.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.bind.annotation.*;
@RestController
@RequestMapping("/api/v1/inventory")
@ConditionalOnProperty(name="identity.http.enabled",havingValue="true")
public final class InventoryController {
 private final SessionService sessions;private final MembershipAccess memberships;private final BusinessAuthorization authorization;private final VendorInventory inventory;private final SessionTransportPolicy policy;private final LoginThrottle throttle;private final ResourceRevisions revisions;private final TransactionTemplate tx;private final byte[] key;private final Clock clock;private final StockCursors cursors;private final InventoryReconciliation reconciliation;private final ReconciliationCursors reconciliationCursors;
 InventoryController(SessionService sessions,MembershipAccess memberships,BusinessAuthorization authorization,VendorInventory inventory,InventoryReconciliation reconciliation,SessionTransportPolicy policy,LoginThrottle throttle,ResourceRevisions revisions,PlatformTransactionManager manager,Clock clock,@Value("${identity.http.revision-key}")String key,@Value("${inventory.cursor.previous-key:}")String previous,@Value("${inventory.cursor.previous-until:}")String until,@Value("${identity.http.replay-fingerprint-key:${identity.http.revision-key}}")String fingerprintKey){this.sessions=sessions;this.memberships=memberships;this.authorization=authorization;this.inventory=inventory;this.reconciliation=reconciliation;this.policy=policy;this.throttle=throttle;this.revisions=revisions;this.clock=clock;this.key=Base64.getDecoder().decode(fingerprintKey);this.cursors=new StockCursors(Base64.getDecoder().decode(key),previous.isEmpty()?null:Base64.getDecoder().decode(previous),until.isEmpty()?null:Instant.parse(until),clock);this.reconciliationCursors=new ReconciliationCursors(Base64.getDecoder().decode(key),previous.isEmpty()?null:Base64.getDecoder().decode(previous),until.isEmpty()?null:Instant.parse(until),clock);tx=new TransactionTemplate(manager);tx.setTimeout(10);}
 @GetMapping("/tracking") TrackingResult tracking(HttpServletRequest r){AuthController.noBody(r);AuthController.noQuery(r);var s=policy.select(r);admit(s,false);return tx.execute(status->{var scope=scope(s,false,null);var c=inventory.tracking(scope.organizationId());activity(s);return new TrackingResult(c.vendor(),revisions.encode("tracking/v1",c.vendor(),c.revision()),c.enabled());});}
 @GetMapping("/products/{productId}") Result get(@PathVariable String productId,HttpServletRequest r){AuthController.noBody(r);AuthController.noQuery(r);UUID product=ContactRequests.id(productId,"PATH","productId");var s=policy.select(r);admit(s,false);return tx.execute(status->{var scope=scope(s,false,null);var item=inventory.get(scope.organizationId(),product);activity(s);return response(item);});}
 @PutMapping("/products/{productId}") Result set(@PathVariable String productId,HttpServletRequest r)throws IOException{return write(productId,r,"ABSOLUTE");}
 @PostMapping("/products/{productId}/adjustments") Result adjust(@PathVariable String productId,HttpServletRequest r)throws IOException{return write(productId,r,"DELTA");}
 @PostMapping("/products/{productId}/confirmation") Result confirm(@PathVariable String productId,HttpServletRequest r)throws IOException{return write(productId,r,"CONFIRM");}
 private Result write(String productId,HttpServletRequest r,String operation)throws IOException{AuthController.noQuery(r);UUID product=ContactRequests.id(productId,"PATH","productId");boolean delta=operation.equals("DELTA"),confirmation=operation.equals("CONFIRM");var input=confirmation?new StockRequests.Input(ContactRequests.revisionCommand(r),0,null):StockRequests.input(r,delta);UUID replayKey=delta?StockRequests.key(r):null;var s=policy.select(r);String csrf=s.transport()==SessionTransport.BROWSER?AuthController.csrfHeader(r):null;UUID actor=admit(s,true);byte[] digest=StockRequests.digest(operation,key,product,input.expected(),input.quantity(),input.reason());byte[] identity=delta?StockRequests.digest("key",key,replayKey):digest;
  return tx.execute(status->{inventory.lockReplay(actor,operation,identity);var scope=scope(s,true,csrf);var replay=inventory.replay(scope.accountId(),scope.organizationId(),product,operation,identity,digest);if(replay.isPresent()){activity(s);var receipt=replay.get();return response(receipt.item(),receipt.originalRevision()==null?legacyToken(receipt.item()):receipt.originalRevision());}var current=inventory.get(scope.organizationId(),product);if(!delta&&!java.security.MessageDigest.isEqual(token(current).getBytes(java.nio.charset.StandardCharsets.US_ASCII),input.expected().getBytes(java.nio.charset.StandardCharsets.UTF_8))){throw new RevisionConflict(token(current));}Item item=delta?inventory.adjust(scope.accountId(),scope.organizationId(),product,input.quantity(),input.reason()):confirmation?inventory.confirm(scope.accountId(),scope.organizationId(),product):inventory.set(scope.accountId(),scope.organizationId(),product,input.quantity(),input.reason());inventory.remember(scope.accountId(),operation,identity,digest,item,token(item));activity(s);return response(item);});
 }
 @GetMapping("/events") Page events(HttpServletRequest r){AuthController.noBody(r);var q=StockRequests.query(r);var s=policy.select(r);admit(s,false);return tx.execute(status->{var scope=scope(s,false,null);var p=q.cursor()==null?null:cursors.decode(q.cursor(),scope.organizationId(),q.product(),q.size());var page=inventory.events(scope.organizationId(),q.product(),q.size(),p==null?null:p.at(),p==null?null:p.id());String next=null;if(page.more()){var last=page.items().getLast();next=cursors.encode(scope.organizationId(),q.product(),q.size(),new StockCursors.Position(last.createdAt(),last.id(),p==null?clock.instant().plusSeconds(86400):p.expires()));}activity(s);return new Page(page.items().stream().map(e->new EventResult(e.id(),e.productId(),e.type(),e.before(),e.after(),e.delta(),e.reason(),e.actorAccountId(),e.orderId(),AccountResponses.time(e.createdAt()))).toList(),next);});}
 @PostMapping("/tracking/disable") TrackingResult disable(HttpServletRequest r)throws IOException{AuthController.noQuery(r);String expected=ContactRequests.revisionCommand(r);var s=policy.select(r);String csrf=csrf(s,r);admit(s,true);byte[] identity=StockRequests.digest("disable",key,expected);return tx.execute(status->{var scope=scope(s,true,csrf);var replay=reconciliation.replay(scope.accountId(),scope.organizationId(),"DISABLE",identity);if(replay.isPresent()){activity(s);return trackingResponse(replay.get().tracking());}var current=inventory.tracking(scope.organizationId());requireRevision(expected,revisions.encode("tracking/v1",current.vendor(),current.revision()));var result=reconciliation.disable(scope.accountId(),scope.organizationId());reconciliation.remember(scope.accountId(),scope.organizationId(),"DISABLE",identity,new InventoryReconciliation.Receipt(null,result));activity(s);return trackingResponse(result);});}
 @PostMapping("/reconciliations") org.springframework.http.ResponseEntity<PreviewResult> prepare(HttpServletRequest r){AuthController.noBody(r);AuthController.noQuery(r);var s=policy.select(r);String csrf=csrf(s,r);admit(s,true);return tx.execute(status->{var scope=scope(s,true,csrf);var p=reconciliation.prepare(scope.accountId(),scope.organizationId());activity(s);return org.springframework.http.ResponseEntity.created(java.net.URI.create("/api/v1/inventory/reconciliations/"+p.id())).body(previewResponse(p));});}
 @GetMapping("/reconciliations/{previewId}") PreviewResult preview(@PathVariable String previewId,HttpServletRequest r){AuthController.noBody(r);AuthController.noQuery(r);UUID id=ContactRequests.id(previewId,"PATH","previewId");var s=policy.select(r);admit(s,false);return tx.execute(status->{var scope=scope(s,false,null);var p=reconciliation.get(scope.organizationId(),id);activity(s);return previewResponse(p);});}
 @GetMapping("/reconciliations/{previewId}/lines") LinesResult lines(@PathVariable String previewId,HttpServletRequest r){AuthController.noBody(r);UUID id=ContactRequests.id(previewId,"PATH","previewId");var q=ReconciliationRequests.query(r);var s=policy.select(r);admit(s,false);return tx.execute(status->{var scope=scope(s,false,null);var p=reconciliation.get(scope.organizationId(),id);var position=q.cursor()==null?null:reconciliationCursors.decode(q.cursor(),scope.organizationId(),id,p.generation(),q.size());var page=reconciliation.lines(scope.organizationId(),id,q.size(),position==null?null:position.id());String next=page.more()?reconciliationCursors.encode(scope.organizationId(),id,p.generation(),q.size(),new ReconciliationCursors.Position(page.items().getLast().productId(),p.expiresAt())):null;activity(s);return new LinesResult(page.items().stream().map(l->new LineResult(l.productId(),lineToken(scope.organizationId(),l),l.availableCount(),l.creditQuantity(),l.acknowledged())).toList(),next,previewToken(p));});}
 @PutMapping("/reconciliations/{previewId}/lines") PreviewResult acknowledge(@PathVariable String previewId,HttpServletRequest r)throws IOException{AuthController.noQuery(r);UUID id=ContactRequests.id(previewId,"PATH","previewId");var b=ReconciliationRequests.batch(r);var s=policy.select(r);String csrf=csrf(s,r);admit(s,true);byte[] identity=StockRequests.digest("acknowledge",key,id,b.expected(),b.lines());return tx.execute(status->{var scope=scope(s,true,csrf);var replay=reconciliation.replay(scope.accountId(),scope.organizationId(),"ACKNOWLEDGE",identity);if(replay.isPresent()){activity(s);return previewResponse(replay.get().preview());}var p=reconciliation.get(scope.organizationId(),id);requireRevision(b.expected(),previewToken(p));var candidates=new ArrayList<InventoryReconciliation.Candidate>();for(var raw:b.lines()){var line=reconciliation.line(scope.organizationId(),id,raw.productId());requireRevision(raw.expectedRevision(),lineToken(scope.organizationId(),line));candidates.add(new InventoryReconciliation.Candidate(raw.productId(),line.sourceRevision(),raw.availableCount()));}var result=reconciliation.acknowledge(scope.accountId(),scope.organizationId(),id,candidates);reconciliation.remember(scope.accountId(),scope.organizationId(),"ACKNOWLEDGE",identity,new InventoryReconciliation.Receipt(result,null));activity(s);return previewResponse(result);});}
 @PostMapping("/reconciliations/{previewId}/confirmation") TrackingResult enable(@PathVariable String previewId,HttpServletRequest r)throws IOException{AuthController.noQuery(r);UUID id=ContactRequests.id(previewId,"PATH","previewId");String expected=ReconciliationRequests.confirmation(r);var s=policy.select(r);String csrf=csrf(s,r);admit(s,true);byte[] identity=StockRequests.digest("enable",key,id,expected);return tx.execute(status->{var scope=scope(s,true,csrf);var replay=reconciliation.replay(scope.accountId(),scope.organizationId(),"ENABLE",identity);if(replay.isPresent()){activity(s);return trackingResponse(replay.get().tracking());}var p=reconciliation.get(scope.organizationId(),id);requireRevision(expected,previewToken(p));var result=reconciliation.enable(scope.accountId(),scope.organizationId(),id);reconciliation.remember(scope.accountId(),scope.organizationId(),"ENABLE",identity,new InventoryReconciliation.Receipt(null,result));activity(s);return trackingResponse(result);});}
 private String csrf(SessionTransportPolicy.Selected s,HttpServletRequest r){return s.transport()==SessionTransport.BROWSER?AuthController.csrfHeader(r):null;}
 private void requireRevision(String expected,String actual){if(!java.security.MessageDigest.isEqual(expected.getBytes(java.nio.charset.StandardCharsets.UTF_8),actual.getBytes(java.nio.charset.StandardCharsets.US_ASCII))){throw new RevisionConflict(actual);}}
 private String previewToken(InventoryReconciliation.Preview p){return revisions.encode("reconciliation/v1",p.id(),p.revision());}
 private String lineToken(UUID vendor,InventoryReconciliation.Line l){return revisions.encode("stock/v1",l.productId(),l.sourceRevision())+"."+revisions.encode("stockepoch/v1",vendor,l.sourceEpoch());}
 private TrackingResult trackingResponse(Tracking t){return new TrackingResult(t.vendor(),revisions.encode("tracking/v1",t.vendor(),t.revision()),t.enabled());}
 private PreviewResult previewResponse(InventoryReconciliation.Preview p){return new PreviewResult(p.id(),previewToken(p),AccountResponses.time(p.expiresAt()),p.productCount(),p.confirmedCount());}
 record PreviewResult(UUID id,String revision,String expiresAt,long productCount,long confirmedCount){}
 record LineResult(UUID productId,String expectedRevision,int availableCount,long cancellationCreditQuantity,boolean acknowledged){}
 record LinesResult(List<LineResult> items,String nextCursor,String previewRevision){}
 private BusinessScope scope(SessionTransportPolicy.Selected s,boolean write,String csrf){var principal=sessions.authenticateForOrganizationWrite(s.secret(),s.transport());if(write&&s.transport()==SessionTransport.BROWSER){sessions.requireCsrf(s.secret(),csrf);}var member=memberships.lockForAuthorization(principal.accountId()).orElseThrow(()->new BusinessAccessDenied(BusinessAccessDenied.Reason.INACCESSIBLE_SCOPE));if(member.type()!=OrganizationType.VENDOR){throw new BusinessAccessDenied(BusinessAccessDenied.Reason.INACCESSIBLE_SCOPE);}return authorization.require(principal.accountId(),member.organizationId(),member.country(),BusinessCapability.EDIT_STOCK);}
 private UUID admit(SessionTransportPolicy.Selected s,boolean write){UUID actor=tx.execute(status->write?sessions.replayAdmissionAccount(s.secret(),s.transport()):sessions.authenticate(s.secret(),s.transport()).accountId());throttle.admitApi(actor,write);return actor;}
 private void activity(SessionTransportPolicy.Selected s){sessions.recordSuccessfulActivity(s.secret(),s.transport());}
 private String token(Item i){return revisions.encode("stock/v1",i.productId(),i.revision())+"."+revisions.encode("stockepoch/v1",i.vendor(),i.epoch());}
 private Result response(Item i){return response(i,token(i));}
 private String legacyToken(Item i){var legacy=new ResourceRevisions(key);return legacy.encode("stock/v1",i.productId(),i.revision())+"."+legacy.encode("stockepoch/v1",i.vendor(),i.epoch());}
 private Result response(Item i,String originalRevision){return new Result(i.productId(),originalRevision,i.productId(),i.availableCount(),i.trackingEnabled(),i.confirmationRequired(),i.creditQuantity(),i.maximumSettableCount());}
 record TrackingResult(UUID id,String revision,boolean enabled){}
 record Result(UUID id,String revision,UUID productId,Integer availableCount,boolean trackingEnabled,boolean confirmationRequired,long cancellationCreditQuantity,long maximumSettableCount){}
 record EventResult(UUID id,UUID productId,String type,Integer before,int after,int delta,String reason,UUID actorAccountId,UUID orderId,String createdAt){}
 record Page(List<EventResult> items,String nextCursor){}
}
